355	// GitHub hands labels back as objects on the issues API and as bare strings in
356	// some fixtures; accept either.
357	export const labelNames = (issue) =>
358	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
359	
360	export const hasLabel = (issue, name) => labelNames(issue).includes(name);
361	
362	// Title. The optional qualifier exists ONLY for deliberately concurrent items —
363	// a fan-out naming its target — and it is part of the identity the same-title
364	// mutex reads (DESIGN §6.1). Nothing ever encodes a date here: that was the slot
365	// grammar, and the issue number is the identity (DESIGN §5).
366	export const workItemTitle = ({ pack, task, qualifier = null }) =>
367	  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;
368	
369	// pack and task ids are single path segments; the qualifier is whatever follows.
370	const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;
371	
372	// The pack half is canonicalized on the way out. A work item's title is STORED
373	// DATA — it sits on an open GitHub issue that outlives any one converge — so items
374	// filed before a pack was renamed still carry the old spelling. Read literally, the
375	// scheduler run would not recognise its own live item, would file a second one beside it, and
376	// would leave the first orphaned in the queue with nothing ever draining it.
377	export function parseWorkItemTitle(title) {
378	  const m = TITLE_RE.exec(String(title ?? '').trim());
379	  return m ? { pack: canonicalPackId(m[1]), task: m[2], qualifier: m[3]?.trim() || null } : null;
380	}
381	
382	export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;
383	
384	// The `<pack>/<task>` id a WORKER PATH names — the identity half a marked issue's
385	// title cannot carry (DESIGN §16.1), read off the path its machine block names. Two
386	// shapes, because tasks have two homes: a declared pack's, and the engine's own
387	// built-in root. The `.claudinite/shared/` prefix is optional in both — a member's
388	// engine is mounted there and the canon runs its own tree.
389	//
390	// It is a PARSE, not a lookup: anything that must know the task exists at HEAD
391	// resolves the path against the discovered task set instead (the executor does).
392	const PACK_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/tasks\/([^/]+)\/[^/]+$/;
393	const BUILT_IN_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?engine\/scheduler\/queue\/tasks\/([^/]+)\/[^/]+$/;
394	
395	export function taskIdFromPath(path) {
396	  const p = String(path ?? '');
397	  const pack = PACK_TASK_PATH_RE.exec(p);
398	  if (pack) return { pack: canonicalPackId(pack[1]), task: pack[2] };
399	  const builtIn = BUILT_IN_TASK_PATH_RE.exec(p);
400	  return builtIn ? { pack: 'engine', task: builtIn[1] } : null;
401	}
402	
403	// STANDING OR AD-HOC, DERIVED (DESIGN §15.26). A task's standing item is the one
404	// the generator files at an anchor: its title names the task and nothing else, and
405	// the task it names is on a calendar. Everything else is ad-hoc — a `manual` task
406	// (which has no anchor to stand for) and every qualified item (a fan-out target, a
407	// request naming its issue), each of which may legitimately run beside the
408	// occurrence rather than being it.
409	//
410	// It is read off the item and the declaration at HEAD rather than off a label the
411	// creator applied, because the two could disagree: a marker says what its writer
412	// believed, the structure says what the item IS, and the guards that consume this
413	// (the occurrence guard, the dedupe, the `after` yield) are only sound on the
414	// second. `frequency` is the declared frequency of the task the title names —
415	// absent when the repo no longer carries it, which is ad-hoc by the same rule.
416	export function isStandingItem(item, frequency) {
417	  const parsed = parseWorkItemTitle(item?.title ?? item);
418	  return !!parsed && parsed.qualifier === null && frequency != null && frequency !== 'manual';
419	}
